const decode = value => String(value || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&#39;|&apos;/gi, "'").replace(/&quot;/gi, '"').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n)).replace(/\s+/g, ' ').trim();
const norm = value => decode(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const starts = [...html.matchAll(/<span[^>]*itemprop=["']startDate["'][^>]*content=["']([^"']+)["'][^>]*>/gi)];
const parsed = [];
for (let i = 0; i < starts.length; i++) {
  const date = starts[i][1];
