const tokens = value => new Set(clean(value).split(' ').filter(Boolean));
const similarity = (a, b) => { const A = tokens(a), B = tokens(b); if (!A.size || !B.size) return 0; const both = [...A].filter(x => B.has(x)).length; return both / new Set([...A, ...B]).size; };
const input = $json;
const body = input.body ?? input.data ?? {};
const response = typeof body === 'string' ? (() => { try { return JSON.parse(body); } catch { return {}; } })() : body;
const choices = Array.isArray(response.data) ? response.data : [];
let best = null, bestScore = 0;
for (const track of choices) { const artistScore = similarity(input.artist, track.artist?.name || track.artist); const titleScore = similarity(input.title, track.title); const score = artistScore * 0.55 + titleScore * 0.45; if (score > bestScore) { bestScore = score; best = track; } }
const matched = Boolean(best && bestScore >= 0.72);
const rank = matched ? Number(best.rank || 0) : 0;
// Deezer exposes rank, not Spotify-style popularity. This 0-100 helper is explicitly labelled Deezer and keeps rank too.
const deezer_popularity = rank ? Math.max(1, Math.min(100, Math.round(Math.log10(rank + 1) / 6 * 100))) : 0;
